A natural idea is to solve the \emph{joint approximate diagonalization of matrices} (JADM) problem, which consists in minimizing
\begin{equation}\label{eq:sym_tensor_diagonalization-gener-0}
f(\matr{Z}) = \sum_{\ell=1}^{\matrelem{L}} \|\offdiag{\matr{W}^{(\ell)}}\|^2,
\end{equation}
where $\matr{Z}\in\mathbb{C}^{n\times m}$ is a full column rank matrix, and $\offdiag{\cdot}$ is the \emph{zero diagonal} operator, setting all the diagonal elements of a square matrix in $\mathbb{C}^{m\times m}$ to zero.

\begin{equation}\label{eq:sym_tensor_diagonalization-gener-0}
f(\matr{Z}) = \sum_{\ell=1}^{\matrelem{L}} \|\offdiag{\matr{W}^{(\ell)}}\|^2,
\end{equation}

We define the \emph{rectangular special linear set} as
\begin{align}\label{eq:def_rsl}
\textbf{RSL}(m,n,\mathbb{C}) \stackrel{\sf def}{=} \{\matr{Z}\in\mathbb{C}^{n\times m}, \matr{Z}^{{\sf H}}\matr{Z}\in\mathbf{SL}_{m}(\mathbb{C})\}.

\begin{align}\label{eq:def_rsl}
\textbf{RSL}(m,n,\mathbb{C}) \stackrel{\sf def}{=} \{\matr{Z}\in\mathbb{C}^{n\times m}, \matr{Z}^{{\sf H}}\matr{Z}\in\mathbf{SL}_{m}(\mathbb{C})\}.
\end{align}

\begin{equation}\label{eq:sym_tensor_diagonalization-gener-0-equi}
f: \mathbf{St}(m,n,\mathbb{C})\times\mathbf{SL}_{m}(\mathbb{C})\rightarrow\mathbb{R}^{+},\ \ (\matr{Y},\matr{X})\mapsto \sum_{\ell=1}^{\matrelem{L}} \|\offdiag{\matr{W}^{(\ell)}}\|^2,
\end{equation}

\begin{equation}\label{eq:sym_tensor_diagonalization-gener-1}
g: \mathbf{SL}_{m}(\mathbb{C})\rightarrow\mathbb{R}^{+},\ \ \matr{X}\mapsto  g(\matr{X})=  \sum_{\ell=1}^{\matrelem{L}} \|\offdiag{\matr{W}^{(\ell)}}\|^2,
\end{equation}

Then their \emph{global convergence}\footnote{For any starting point, the iterates converge to a limit point as a whole sequence.} and \emph{weak convergence}\footnote{Every accumulation point is a stationary point, \emph{i.e.}, the Riemannian gradient is equal to 0.} will be established in \Cref{sec:BCD-G} using the \emph{\L{}ojasiewicz gradient inequality} \cite{loja1965ensembles,lojasiewicz1993geometrie,absil2005convergence,Usch15:pjo}, under the assumption that the iterates $\matr{\omega}_{k}$ are bounded, that is, 
there exists a universal positive constant  $\mathrm{M}_{\omega}>0$ such that 
\begin{equation}\label{eq:condi_bounded_X_gene}
\|\matr{\omega}_{k}\|\leq \mathrm{M}_{\omega}
\end{equation}
always holds for all $k\geq 1$.

\begin{equation}\label{eq:condi_bounded_X_gene}
\|\matr{\omega}_{k}\|\leq \mathrm{M}_{\omega}
\end{equation}

\begin{equation}\label{eq:condi_bounded_X_gene-2}
\|\matr{X}_{k}\|\leq \mathrm{M}_{\matr{X}}
\end{equation}

To minimize a smooth function 
\begin{equation}\label{definition-f-general}
\tilde{f}:\ \mathcal{M}_1\times\mathcal{M}_2\times\cdots\times\mathcal{M}_d \longrightarrow \mathbb{R}^{+},
\end{equation}
a popular approach is the \emph{block coordinate descent} (BCD) algorithm  \cite{bertsekas1997nonlinear,luo1992convergence,luo1993error,wright2015coordinate,xu2013block,li2019polar}.

\begin{equation}\label{definition-f-general}
