\caption{BCD-G algorithm}\label{alg:BCD-G-RL}
\begin{algorithmic}[1]
\STATE{{\bf Input:} A starting point $\matr{\omega}_{0}=(\matr{Y}_0,\matr{X}_0)$, a positive constant $0<\upsilon<\sqrt{2}/2$.}
\STATE{{\bf Output:} Sequence of iterates $\matr{\omega}_{k}=(\matr{Y}_k,\matr{X}_k)$.} 
\FOR{$k=1,2,\cdots,$}
\STATE Choose $t_k=1$ or $2$ such that the Riemannian gradients satisfy 
\begin{equation}
\|\ProjGrad{f_{t_k}}{\matr{\omega}_{k-1}}\|\geq\upsilon\|\ProjGrad{f}{\matr{\omega}_{k-1}}\|;
\label{eq:inequality_BCD_G}
\end{equation}
\vspace{-0.5cm}
\IF {$t_k=1$} 
\STATE Update $\matr{Y}_{k}$ using the line search descent method (cf. \Cref{subsec:line_seach});
\STATE Set $\matr{X}_{k}=\matr{X}_{k-1}$;
\ELSE
\STATE Set $\matr{Y}_{k}=\matr{Y}_{k-1}$; 
\STATE Update $\matr{X}_{k}$ using  elementary transformations (cf. \autoref{alg:jacobi-LU-G_c} to \ref{alg:jacob-GU-G_c}).
\ENDIF 
\ENDFOR
\end{algorithmic}

\begin{equation}
\|\ProjGrad{f_{t_k}}{\matr{\omega}_{k-1}}\|\geq\upsilon\|\ProjGrad{f}{\matr{\omega}_{k-1}}\|;
\label{eq:inequality_BCD_G}
\end{equation}

\begin{align}\label{eq:grad_relation}
\ProjGrad{f}{\matr{\omega}} = (\ProjGrad{f_1}{\matr{\omega}},\ \ProjGrad{f_2}{\matr{\omega}}),
\end{align}

\caption{Jacobi-G algorithm}\label{alg:jacobi-LU-G_c-1}
\begin{algorithmic}[1]
\STATE{{\bf Input:} A  starting point $\matr{X}_{0}$.}
\STATE{{\bf Output:} Sequence of iterates $\{\matr{X}_{k}\}_{k\ge1}$.}
\FOR{$k=1,2,\cdots,$}
\STATE  Update $\matr{X}_k$ using elementary transformations (cf. \autoref{alg:jacobi-LU-G_c} to \ref{alg:jacobi-LQ-G_c}).
\ENDFOR
\end{algorithmic}

