\label{def:Lojasiewicz}
Let $\mathcal{M} \subseteq \mathbb{R}^d$ be a Riemannian submanifold,
and $\varphi: \mathcal{M} \to \mathbb{R}$ be a differentiable function.
The function $\varphi: \mathcal{M} \to \mathbb{R}$ is said to satisfy a \emph{\L{}ojasiewicz gradient inequality} at $\vect{x} \in \mathcal{M}$, if there exist
$\delta>0$, $\zeta\in (0,\frac{1}{2}]$ and a neighborhood $\mathcal{U}$ in $\mathcal{M}$ of $\vect{x}$ such that for all $\vect{y}\in\mathcal{U}$, it follows that 
\begin{equation}\label{eq:Lojasiewicz}
|{\varphi}(\vect{y})-{\varphi}(\vect{x})|^{1-\zeta}\leq \delta\|\ProjGrad{\varphi}{\vect{y}}\|.
\end{equation}

\begin{equation}\label{eq:Lojasiewicz}
|{\varphi}(\vect{y})-{\varphi}(\vect{x})|^{1-\zeta}\leq \delta\|\ProjGrad{\varphi}{\vect{y}}\|.
\end{equation}

\label{lemma-SU15}
Let $\mathcal{M}\subseteq\mathbb{R}^d$ be an analytic submanifold\footnote{See {\cite[Definition 2.7.1]{krantz2002primer}} or \cite[Definition 5.1]{LUC2018} for a definition of an analytic submanifold.} and $\varphi: \mathcal{M} \to \mathbb{R}$ be a real analytic function.
Then $\varphi$ satisfies a \L{}ojasiewicz gradient inequality \cref{eq:Lojasiewicz} at any $\vect{x}\in \mathcal{M}$.

\label{theorem-SU15}
Let $\mathcal{M}\subseteq\mathbb{R}^d$ be an analytic submanifold
and 
$\{\vect{x}_k\}_{k\geq 1}\subseteq\mathcal{M}$.
Suppose that $\varphi$ is real analytic and, for large enough $k$,\\
(i) there exists $\sigma>0$ such that
\begin{equation*}
\varphi(\vect{x}_{k})-{\varphi}(\vect{x}_{k+1})\geq \sigma\|\ProjGrad{\varphi}{\vect{x}_k}\|\|\vect{x}_{k+1}-\vect{x}_{k}\|;
\end{equation*}
(ii) $\ProjGrad{\varphi}{\vect{x}_k}=0$ implies that $\vect{x}_{k+1}=\vect{x}_{k}$.\\
Then, if $\vect{x}_*$ is an accumulation point of $\{\vect{x}_k\}_{k\geq 1}$, it is the limit point.

\begin{equation*}
\varphi(\vect{x}_{k})-{\varphi}(\vect{x}_{k+1})\geq \sigma\|\ProjGrad{\varphi}{\vect{x}_k}\|\|\vect{x}_{k+1}-\vect{x}_{k}\|;
\end{equation*}

\label{theorem-SU15-2}
Suppose that, in \Cref{alg:BCD-G-RL} for cost function \cref{eq:sym_tensor_diagonalization-gener-0-equi}, the iterates $\{\matr{\omega}_k\}_{k\geq 1}$ satisfy that, for large enough $k$,\\
(i) there exists $\sigma>0$ such that
\begin{equation}\label{eq:sufficient_descent-2}
f(\matr{\omega}_{k-1})-f(\matr{\omega}_{k})\geq\sigma\|\ProjGrad{f_{t_k}}{\matr{\omega}_{k-1}}\|\|\matr{\omega}_{k}-\matr{\omega}_{k-1}\|;
\end{equation}
(ii) $\ProjGrad{f_{t_k}}{\matr{\omega}_{k-1}}=0$ implies that $\matr{\omega}_{k}=\matr{\omega}_{k-1}$.\\
Then, if $\matr{\omega}_*$ is an accumulation point of the iterates $\{\matr{\omega}_k\}_{k\geq 1}$, it is the limit point.

\begin{equation}\label{eq:sufficient_descent-2}
f(\matr{\omega}_{k-1})-f(\matr{\omega}_{k})\geq\sigma\|\ProjGrad{f_{t_k}}{\matr{\omega}_{k-1}}\|\|\matr{\omega}_{k}-\matr{\omega}_{k-1}\|;
\end{equation}

