Denote $\matr{V}=\matr{A}\matr{Z}=[\vect{v}_1,\cdots,\vect{v}_m]\in\mathbb{C}^{n\times m}$ and $\overbar{\matr{V}}=\matr{A}^{{\blacklozenge}}\matr{Z}=[\bar{\vect{v}}_1,\cdots,\bar{\vect{v}}_m]\in\mathbb{C}^{n\times m}$. 
Denote $\matr{Z}=[\vect{z}_1,\cdots,\vect{z}_m]$. 
Then the Euclidean gradient is
\begin{align*}
\nabla\tilde{p}(\matr{Z})  = 2\left(\sum_{j\neq 1}\vect{v}_{j}\vect{v}_{j}^{{\sf H}}\vect{z}_1,\cdots,\sum_{j\neq m}\vect{v}_{j}\vect{v}_{j}^{{\sf H}}\vect{z}_m\right)+
2\left(\sum_{j\neq 1}\bar{\vect{v}}_{j}(\bar{\vect{v}}_{j})^{{\sf H}}\vect{z}_1,\cdots,\sum_{j\neq m}\bar{\vect{v}}_{j}(\bar{\vect{v}}_{j})^{{\sf H}}\vect{z}_m\right).
\end{align*}
In particular, it satisfies 
\begin{align}\label{eq:eucli_grad_h}
\matr{Z}\matr{Z}^{{\sf H}}\nabla\tilde{p}(\matr{Z})   = 2\matr{Z}\Upsilon(\matr{W}),
\end{align}
where $\Upsilon(\matr{W})\in\mathbb{C}^{m\times m}$ is defined as 
\begin{equation}\label{eq:Upsilon_W}
\Upsilon(\matr{W})\stackrel{\sf def}{=}\left\{
\begin{aligned}
\matr{W}\offdiag{\matr{W}}^{{\sf H}} + \matr{W}^{H}\offdiag{\matr{W}},\ \ & \textrm{if}\  (\cdot)^{{\blacklozenge}}=(\cdot)^{{\sf H}}; \\
\matr{W}^{*}\offdiag{\matr{W}}^{{\sf T}} + \matr{W}^{H}\offdiag{\matr{W}},\ \ & \textrm{if}\  (\cdot)^{{\blacklozenge}}=(\cdot)^{{\sf T}}.
\end{aligned}
\right.
\end{equation}

\begin{equation*}
\tilde{p}: \mathbb{C}^{n\times m}\rightarrow\mathbb{R}^{+},\ \ \matr{Z}\mapsto  \|\offdiag{\matr{W}}\|^2,
\end{equation*}

\begin{align}\label{eq:eucli_grad_h}
\matr{Z}\matr{Z}^{{\sf H}}\nabla\tilde{p}(\matr{Z})   = 2\matr{Z}\Upsilon(\matr{W}),
\end{align}

\begin{equation}\label{eq:Upsilon_W}
