\matr{Y}^{{\sf H}}\nabla\textit{p}(\matr{Y}) =  2(\matr{X}^{{\sf H}})^{-1}\sum_{\ell=1}^{\matrelem{L}}\Upsilon(\matr{W}^{(\ell)})\matr{X}^{{\sf H}},\label{eq:euclidean_grad-1}
\end{align}
where $\Upsilon(\matr{W}^{(\ell)})$ is as in \cref{eq:Upsilon_W}.

\begin{align}
\matr{Y}^{{\sf H}}\nabla\textit{p}(\matr{Y}) =  2(\matr{X}^{{\sf H}})^{-1}\sum_{\ell=1}^{\matrelem{L}}\Upsilon(\matr{W}^{(\ell)})\matr{X}^{{\sf H}},\label{eq:euclidean_grad-1}
\end{align}

\begin{align*}
