In this method, we choose the next iteration as 
\begin{equation}\label{eq:U_k_update}
\matr{Y}_{k} ={\rm Exp}_{\matr{Y}_{k-1}}(t_{k-1}\matr{V}_{k-1}),
\end{equation}
where $\matr{V}_{k-1}$ is the \emph{search direction}, $t_{k-1}$ is the \emph{step size} and ${\rm Exp}_{\matr{Y}_{k-1}}$ is the exponential map defined in \cref{eq:ex_sl_pr}.

\begin{equation}\label{eq:U_k_update}
\matr{Y}_{k} ={\rm Exp}_{\matr{Y}_{k-1}}(t_{k-1}\matr{V}_{k-1}),
\end{equation}

\begin{equation}\label{eq:cond_driect}
\langle\ProjGrad{p}{\matr{Y}_{k-1}},\matr{V}_{k-1}\rangle_{\matr{Y}_{k-1}}\leq -\delta_{s} \|\ProjGrad{p}{\matr{Y}_{k-1}}\|\|\matr{V}_{k-1}\|,
\end{equation}

We say that the step size $t_{k-1}$ satisfies the \emph{Armijo condition}\footnote{It is also known as the \emph{first
Wolfe condition} in the literature.}, if 
\begin{align}\label{eq:cond_step_size}
p(\matr{Y}_{k})\leq p(\matr{Y}_{k-1}) + \delta_{w}t_{k-1}\langle\ProjGrad{p}{\matr{Y}_{k-1}},\matr{V}_{k-1}\rangle_{\matr{Y}_{k-1}},
\end{align}
where $0<\delta_{w}<1$ is a fixed positive constant.

\begin{align}\label{eq:cond_step_size}
p(\matr{Y}_{k})\leq p(\matr{Y}_{k-1}) + \delta_{w}t_{k-1}\langle\ProjGrad{p}{\matr{Y}_{k-1}},\matr{V}_{k-1}\rangle_{\matr{Y}_{k-1}},
\end{align}

\begin{align}\label{eq:cond_step_size-2}{\small 
\langle\ProjGrad{p}{\matr{Y}_{k}},\mathbf{D}{\rm Exp}_{\matr{Y}_{k-1}}(t_{k-1}\matr{V}_{k-1})[\matr{V}_{k-1}]\rangle_{\matr{Y}_{k}}\geq \delta_{c} \langle\ProjGrad{p}{\matr{Y}_{k-1}},\matr{V}_{k-1}\rangle_{\matr{Y}_{k-1}},}
\end{align}

It is not difficult to see that there exists $\mathrm{M}_{e}>0$ such that
\begin{equation*}
\|{\rm Exp}_{\matr{Y}}(\matr{V}_{1})-{\rm Exp}_{\matr{Y}}(\matr{V}_{2})\|\leq \mathrm{M}_{e}\|\matr{V}_{1}-\matr{V}_{2}\|,
\end{equation*}
for any $\matr{Y}\in \mathbf{St}(m,n,\mathbb{C})$ and $\matr{V}_1,\matr{V}_2\in{\rm\bf T}_{\matr{Y}} \mathbf{St}(m,n,\mathbb{C})$.

\begin{equation*}
\|{\rm Exp}_{\matr{Y}}(\matr{V}_{1})-{\rm Exp}_{\matr{Y}}(\matr{V}_{2})\|\leq \mathrm{M}_{e}\|\matr{V}_{1}-\matr{V}_{2}\|,
\end{equation*}

\label{lemma:line_search}
If we choose the next iterate $\matr{Y}_k$ as in \cref{eq:U_k_update} such that the conditions \cref{eq:cond_driect} and \cref{eq:cond_step_size} are both satisfied,
then we have 
\begin{align*}{\small 
p(\matr{Y}_{k-1})-p(\matr{Y}_{k})\geq \delta_{s} \delta_{w}\|\ProjGrad{p}{\matr{Y}_{k-1}}\| \|t_{k-1}\matr{V}_{k-1}\|
\geq \sigma_{p}\|\ProjGrad{p}{\matr{Y}_{k-1}}\| \|\matr{Y}_{k}-\matr{Y}_{k-1}\|,}
\end{align*}
where $\sigma_p=(\delta_{s} \delta_{w})/\mathrm{M}_{e}$.

\begin{align*}{\small 
p(\matr{Y}_{k-1})-p(\matr{Y}_{k})\geq \delta_{s} \delta_{w}\|\ProjGrad{p}{\matr{Y}_{k-1}}\| \|t_{k-1}\matr{V}_{k-1}\|
\geq \sigma_{p}\|\ProjGrad{p}{\matr{Y}_{k-1}}\| \|\matr{Y}_{k}-\matr{Y}_{k-1}\|,}
\end{align*}

\label{lemma:line_search-2}
If we choose the next iterate $\matr{Y}_k$ as in \cref{eq:U_k_update} such that the conditions \cref{eq:cond_driect},  \cref{eq:cond_step_size} and \cref{eq:cond_step_size-2} are all satisfied, then we have 
\begin{equation}\label{eq:cond_weak_h}
p(\matr{Y}_{k-1})-p(\matr{Y}_{k})\geq \eta_p\|\ProjGrad{p}{\matr{Y}_{k-1}}\|^2, 
\end{equation}
where $\eta_p>0$ is a fixed positive constant.

\begin{equation}\label{eq:cond_weak_h}
p(\matr{Y}_{k-1})-p(\matr{Y}_{k})\geq \eta_p\|\ProjGrad{p}{\matr{Y}_{k-1}}\|^2, 
\end{equation}

